#include "../scores.h"
#include <assert.h>
int main(void){SkiScores a={0},b;int i;for(i=20;i>=1;i--){score_insert(&a,1,i*100);score_insert(&a,2,i*200);score_insert(&a,3,i);}assert(a.count[0]==10&&a.value[0][0]==100&&a.value[0][9]==1000);assert(a.value[2][0]==20&&a.value[2][9]==11);assert(score_insert(&a,0,1)==-1);assert(score_insert(&a,1,-1)==-1);assert(scores_write(&a,"score-test.tmp"));assert(scores_read(&b,"score-test.tmp")==1);assert(!memcmp(&a,&b,sizeof(a)));memset(&a,0,sizeof(a));assert(score_insert(&a,3,-20)==0);assert(score_insert(&a,3,-5)==0);assert(a.value[2][0]==-5);assert(scores_write(&a,"score-test.tmp"));assert(scores_read(&b,"score-test.tmp")==1);assert(!memcmp(&a,&b,sizeof(a)));{const char*bad[]={"SkiFreeScores1 11 0 0","SkiFreeScores1 -1 0 0","SkiFreeScores1 1 2147483648 0 0","SkiFreeScores1 0 0 1 -2147483649","SkiFreeScores1 1 abc 0 0","SkiFreeScores1 2 20 10 0 0","SkiFreeScores1 0 0 2 10 20","SkiFreeScores1 1 -1 0 0"};unsigned j;for(j=0;j<sizeof(bad)/sizeof(bad[0]);j++){FILE*f=fopen("score-test.tmp","w");fputs(bad[j],f);fclose(f);assert(scores_read(&b,"score-test.tmp")==-1);assert(!b.count[0]&&!b.count[1]&&!b.count[2]);}memset(&a,0,sizeof(a));assert(score_insert(&a,1,2147483647)==0);assert(score_insert(&a,3,(-2147483647-1))==0);assert(scores_write(&a,"score-test.tmp"));assert(scores_read(&b,"score-test.tmp")==1);assert(!memcmp(&a,&b,sizeof(a)));}puts("SCORES_PASS");return 0;}
